-- Modulo 70 SeguridadSaludOcupacional: equipos de proteccion, entregas de EPP, examenes medicos, incidentes y acciones correctivas.
-- Spec: docs/specs/modulo70-seguridad-salud-ocupacional-backend.md (§4).

CREATE TABLE "EquiposProteccion" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Codigo" character varying(20) NOT NULL,
    "Nombre" character varying(100) NOT NULL,
    "VidaUtilDias" integer NOT NULL,
    "Activo" boolean NOT NULL,
    CONSTRAINT "PK_EquiposProteccion" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_EquiposProteccion_VidaUtilDias" CHECK ("VidaUtilDias" BETWEEN 1 AND 3650)
);
CREATE UNIQUE INDEX "IX_EquiposProteccion_Codigo" ON "EquiposProteccion" ("Codigo");

CREATE TABLE "EntregasEpp" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "EquipoProteccionId" integer NOT NULL,
    "EmpleadoId" integer NOT NULL,
    "FechaEntrega" date NOT NULL,
    "Cantidad" integer NOT NULL,
    "FechaVencimiento" date NOT NULL,
    CONSTRAINT "PK_EntregasEpp" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_EntregasEpp_EquiposProteccion_EquipoProteccionId" FOREIGN KEY ("EquipoProteccionId") REFERENCES "EquiposProteccion" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_EntregasEpp_Empleados_EmpleadoId" FOREIGN KEY ("EmpleadoId") REFERENCES "Empleados" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_EntregasEpp_Cantidad" CHECK ("Cantidad" BETWEEN 1 AND 100),
    CONSTRAINT "CK_EntregasEpp_Fechas" CHECK ("FechaVencimiento" >= "FechaEntrega")
);
CREATE INDEX "IX_EntregasEpp_EquipoProteccionId" ON "EntregasEpp" ("EquipoProteccionId");
CREATE INDEX "IX_EntregasEpp_EmpleadoId" ON "EntregasEpp" ("EmpleadoId");

CREATE TABLE "ExamenesMedicos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "EmpleadoId" integer NOT NULL,
    "Tipo" character varying(20) NOT NULL,
    "Fecha" date NOT NULL,
    "Resultado" character varying(30) NOT NULL,
    "Restricciones" character varying(300),
    "FechaVencimiento" date,
    "Clinica" character varying(150),
    CONSTRAINT "PK_ExamenesMedicos" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ExamenesMedicos_Empleados_EmpleadoId" FOREIGN KEY ("EmpleadoId") REFERENCES "Empleados" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_ExamenesMedicos_Tipo" CHECK ("Tipo" IN ('Ingreso', 'Periodico', 'Retiro')),
    CONSTRAINT "CK_ExamenesMedicos_Resultado" CHECK ("Resultado" IN ('Apto', 'AptoConRestricciones', 'NoApto')),
    CONSTRAINT "CK_ExamenesMedicos_Vencimiento" CHECK (("Tipo" = 'Retiro' AND "FechaVencimiento" IS NULL) OR ("Tipo" <> 'Retiro' AND "FechaVencimiento" > "Fecha"))
);
CREATE INDEX "IX_ExamenesMedicos_EmpleadoId" ON "ExamenesMedicos" ("EmpleadoId");

CREATE TABLE "IncidentesSst" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Numero" character varying(20) NOT NULL,
    "EmpleadoId" integer NOT NULL,
    "Tipo" character varying(30) NOT NULL,
    "Severidad" character varying(20) NOT NULL,
    "Fecha" date NOT NULL,
    "Lugar" character varying(150),
    "Descripcion" character varying(1000) NOT NULL,
    "DiasBaja" integer NOT NULL,
    "Estado" character varying(20) NOT NULL,
    "FechaCierre" date,
    CONSTRAINT "PK_IncidentesSst" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_IncidentesSst_Empleados_EmpleadoId" FOREIGN KEY ("EmpleadoId") REFERENCES "Empleados" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_IncidentesSst_Tipo" CHECK ("Tipo" IN ('AccidenteSinBaja', 'AccidenteConBaja', 'IncidenteSinLesion', 'EnfermedadOcupacional')),
    CONSTRAINT "CK_IncidentesSst_Severidad" CHECK ("Severidad" IN ('Leve', 'Moderada', 'Grave', 'Mortal')),
    CONSTRAINT "CK_IncidentesSst_Estado" CHECK ("Estado" IN ('Abierto', 'Cerrado')),
    CONSTRAINT "CK_IncidentesSst_DiasBaja" CHECK (("Tipo" = 'AccidenteConBaja' AND "DiasBaja" >= 1) OR ("Tipo" <> 'AccidenteConBaja' AND "DiasBaja" = 0))
);
CREATE UNIQUE INDEX "IX_IncidentesSst_Numero" ON "IncidentesSst" ("Numero");
CREATE INDEX "IX_IncidentesSst_EmpleadoId" ON "IncidentesSst" ("EmpleadoId");
CREATE INDEX "IX_IncidentesSst_Fecha" ON "IncidentesSst" ("Fecha");

CREATE TABLE "AccionesCorrectivasSst" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "IncidenteSstId" integer NOT NULL,
    "Descripcion" character varying(500) NOT NULL,
    "Responsable" character varying(150) NOT NULL,
    "FechaCompromiso" date NOT NULL,
    "Completada" boolean NOT NULL,
    "FechaCompletada" date,
    CONSTRAINT "PK_AccionesCorrectivasSst" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AccionesCorrectivasSst_IncidentesSst_IncidenteSstId" FOREIGN KEY ("IncidenteSstId") REFERENCES "IncidentesSst" ("Id") ON DELETE RESTRICT
);
CREATE INDEX "IX_AccionesCorrectivasSst_IncidenteSstId" ON "AccionesCorrectivasSst" ("IncidenteSstId");
